import React, { useState, useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";

const API_URL = "http://localhost:5000/api";

function Gallery() {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchTyped, setSearchTyped] = useState("");

  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();

  const selectedCategory = searchParams.get("category") || "";
  const searchQuery = searchParams.get("search") || "";
  const sortBy = searchParams.get("sort") || "default";

  useEffect(() => {
    setSearchTyped(searchQuery);
    fetch(API_URL + "/categories")
      .then((res) => res.json())
      .then((data) => setCategories(data))
      .catch((err) => console.log("Category error", err));
  }, []);

  useEffect(() => {
    setLoading(true);
    let url = API_URL + "/products?";
    if (searchQuery) url += "search=" + encodeURIComponent(searchQuery) + "&";
    if (selectedCategory) url += "category=" + selectedCategory;

    fetch(url)
      .then((res) => res.json())
      .then((data) => {
        setProducts(data);
        setLoading(false);
      })
      .catch((err) => {
        setError("Could not load products.");
        setLoading(false);
      });
  }, [searchQuery, selectedCategory]);

  const updateUrl = (key, value) => {
    const newParams = new URLSearchParams(searchParams);
    if (value) newParams.set(key, value);
    else newParams.delete(key);
    setSearchParams(newParams, { replace: true });
  };

  const getSortedProducts = () => {
    let list = [...products];
    if (sortBy === "price-asc") list.sort((a, b) => a.price - b.price);
    if (sortBy === "price-desc") list.sort((a, b) => b.price - a.price);
    if (sortBy === "name") list.sort((a, b) => a.name.localeCompare(b.name));
    return list;
  };

  const finalProducts = getSortedProducts();

  return (
    <div className="container py-5">
      {/* --- CUSTOM HOVER STYLES --- */}
      <style>{`
        .product-card {
          transition: transform 0.3s ease, box-shadow 0.3s ease;
          border: 1px solid #eee !important;
          border-radius: 8px;
          overflow: hidden;
        }
        .product-card:hover {
          transform: translateY(-8px);
          box-shadow: 0 12px 24px rgba(0,0,0,0.1);
          border-color: #333 !important;
        }
        .img-container {
          overflow: hidden;
        }
        .product-card:hover img {
          transform: scale(1.08);
        }
        .product-card img {
          transition: transform 0.5s ease;
        }
      `}</style>

      <div className="row">
        {/* Sidebar */}
        <div className="col-md-3">
          <h5 className="mb-4 serif">Filters</h5>
          <div className="mb-4">
            <label className="small fw-bold text-muted mb-2">SEARCH</label>
            <div className="d-flex gap-2">
              <input
                type="text"
                className="form-control form-control-sm"
                placeholder="Search frames..."
                value={searchTyped}
                onChange={(e) => setSearchTyped(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && updateUrl("search", searchTyped)}
              />
              <button className="btn btn-dark btn-sm" onClick={() => updateUrl("search", searchTyped)}>Search</button>
            </div>
          </div>

          <div className="mb-4">
            <label className="small fw-bold text-muted mb-2">COLLECTIONS</label>
            {[{_id: "", name: "All Collections"}, ...categories].map((cat) => (
              <div className="form-check" key={cat._id || 'all'}>
                <input
                  className="form-check-input"
                  type="radio"
                  name="cat"
                  checked={selectedCategory === cat._id}
                  onChange={() => updateUrl("category", cat._id)}
                />
                <label className="form-check-label small">{cat.name}</label>
              </div>
            ))}
          </div>
        </div>

        {/* Grid */}
        <div className="col-md-9">
          <div className="d-flex justify-content-between align-items-center mb-4">
            <h3 className="serif">The Gallery</h3>
            <select 
              className="form-select w-auto form-select-sm" 
              value={sortBy}
              onChange={(e) => updateUrl("sort", e.target.value)}
            >
              <option value="default">Sort By</option>
              <option value="price-asc">Price: Low to High</option>
              <option value="price-desc">Price: High to Low</option>
              <option value="name">Name A-Z</option>
            </select>
          </div>

          {loading ? (
            <p className="text-muted">Loading...</p>
          ) : (
            <div className="row g-4">
              {finalProducts.map((p) => (
                <div className="col-6 col-md-4" key={p._id}>
                  <div 
                    className="card h-100 product-card border-0 bg-white" 
                    onClick={() => navigate("/product/" + p._id)}
                    style={{ cursor: "pointer" }}
                  >
                    <div className="img-container">
                      <img 
                        src={p.image} 
                        className="card-img-top" 
                        alt={p.name} 
                        style={{ height: "280px", objectFit: "cover" }}
                      />
                    </div>
                    <div className="card-body text-center">
                      <h6 className="mb-1 text-uppercase small fw-bold" style={{ letterSpacing: '1px' }}>{p.name}</h6>
                      <p className="text-muted small mb-0">{p.price} EGP</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Gallery;
